-- Katalog lakierów: 686 kolorów, 457 renderów, 664 zdjęcia referencyjne.
--
-- Dlaczego dane jadą migracją, a nie importem: `import-paints.php` wymaga
-- Node.js i repozytorium `e55-paint-to-sample`, więc nie da się go uruchomić
-- na hostingu PHP. Nie da się go też uruchomić lokalnie przeciwko zdalnej
-- bazie - DSN dev i produkcji wskazuje nazwy hostów widoczne tylko z serwera
-- (`localhost` oraz `mysql8:3380`), a zdalny dostęp do MySQL jest zamknięty.
-- Migracja jest jedyną drogą, którą katalog dociera na serwer, i jest zgodna
-- z resztą projektu (patrz `027_restore_e82_model.sql`).
--
-- Migracja 028 zasiewa tylko 3 palety i 6 kolorów Rexor. Ten plik dokłada
-- pełne palety Porsche Paint to Sample i Volkswagena.
--
-- Identyfikatory nie są przepisywane z bazy lokalnej: kolor jest wiązany
-- z paletą przez slug, a render z kolorem i modelem również przez slug.
-- Dzięki temu plik jest niezależny od AUTO_INCREMENT na docelowej bazie.
--
-- `reference_is_public` zostaje FALSE: zdjęcia z galerii Rennbow to cudze
-- materiały, widoczne wyłącznie dla zalogowanego administratora
-- (`docs/PLAN_LAKIERY.md`, decyzja 6).

CREATE TEMPORARY TABLE tmp_paint_colors (
    palette_slug VARCHAR(120) NOT NULL,
    slug VARCHAR(180) NOT NULL,
    code VARCHAR(60) NULL,
    name VARCHAR(200) NOT NULL,
    hex CHAR(7) NOT NULL,
    finish VARCHAR(20) NOT NULL,
    group_name VARCHAR(120) NULL,
    search_alt VARCHAR(500) NULL,
    price_gross_override DECIMAL(12,2) NULL,
    reference_image_path VARCHAR(500) NULL,
    reference_source_url VARCHAR(1000) NULL,
    sort_order INT NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;








-- ON DUPLICATE KEY UPDATE, żeby 6 kolorów Rexor zasianych migracją 028 zostało
-- doprowadzonych do tego samego stanu co lokalnie, a nie zdublowanych.
     price_gross_override, reference_image_path, reference_source_url,
     reference_is_public, sort_order)
SELECT p.id, t.slug, t.code, t.name, t.hex, t.finish, t.group_name, t.search_alt,
       t.price_gross_override, t.reference_image_path, t.reference_source_url,
       FALSE, t.sort_order
FROM tmp_paint_colors t
JOIN paint_palettes p ON p.slug = t.palette_slug
ON DUPLICATE KEY UPDATE
    code = VALUES(code),
    name = VALUES(name),
    hex = VALUES(hex),
    finish = VALUES(finish),
    group_name = VALUES(group_name),
    search_alt = VALUES(search_alt),
    price_gross_override = VALUES(price_gross_override),
    reference_image_path = VALUES(reference_image_path),
    reference_source_url = VALUES(reference_source_url),
    sort_order = VALUES(sort_order);

DROP TEMPORARY TABLE tmp_paint_colors;

CREATE TEMPORARY TABLE tmp_paint_renders (
    palette_slug VARCHAR(120) NOT NULL,
    color_slug VARCHAR(180) NOT NULL,
    model_slug VARCHAR(120) NOT NULL,
    variant VARCHAR(20) NOT NULL,
    image_path VARCHAR(500) NOT NULL,
    thumb_path VARCHAR(500) NULL,
    source VARCHAR(200) NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;






-- `paint_renders` nie ma klucza unikalnego na (kolor, produkt, wariant), więc
-- zamiast ON DUPLICATE KEY pilnujemy braku duplikatu warunkiem NOT EXISTS.
-- Runner wykonuje każdą migrację raz, ale ten plik bywa też wgrywany ręcznie.
SELECT c.id, m.id, t.variant, t.image_path, t.thumb_path, t.source, TRUE
FROM tmp_paint_renders t
JOIN paint_palettes p ON p.slug = t.palette_slug
JOIN paint_colors c ON c.palette_id = p.id AND c.slug = t.color_slug
JOIN bike_models m ON m.slug = t.model_slug
WHERE NOT EXISTS (
    SELECT 1 FROM paint_renders r
    WHERE r.color_id = c.id AND r.model_id = m.id AND r.variant = t.variant
);

DROP TEMPORARY TABLE tmp_paint_renders;
